<?php
declare(strict_types=1);
namespace MarketForecast\Tests;
use MarketForecast\Database\{Connection,Migrator};use MarketForecast\Reliability\ReliabilityRepository;use PHPUnit\Framework\TestCase;
final class ReliabilityRepositoryTest extends TestCase { public function testRunsAreIdempotentAndScoresImmutable():void{$p=tempnam(sys_get_temp_dir(),'rel-');$pdo=Connection::open($p);(new Migrator($pdo))->apply(dirname(__DIR__).'/database/migrations','2026-01-01T00:00:00Z');$pdo->exec("INSERT INTO experiments(experiment_code,name,description,start_at,status,config_json) VALUES('EXP-001','Test','Test','2026-01-01T00:00:00Z','ACTIVE','{}')");$r=new ReliabilityRepository($pdo);$x=['experiment_id'=>1,'source_type'=>'AI_QUANT','window_code'=>'CUMULATIVE','window_end'=>'2026-01-02T00:00:00Z','calculation_version'=>'FRF_2_0','status'=>'COMPLETE','resolved_n'=>10,'created_at'=>'2026-01-02T00:00:00Z'];$id=$r->createRun($x);self::assertNotNull($id);self::assertNull($r->createRun($x));self::assertSame(1,$r->saveScore($id,['fps'=>70,'ecs'=>80,'frs'=>63,'created_at'=>'2026-01-02T00:00:00Z']));self::assertSame(1,(int)$pdo->query('SELECT COUNT(*) FROM reliability_scores')->fetchColumn());@unlink($p);@unlink($p.'-wal');@unlink($p.'-shm');} }
